ALTER TABLE lead_sources MODIFY connector_status ENUM('not_configured','awaiting_credentials','ready_for_test','connected','error','local') NOT NULL DEFAULT 'awaiting_credentials';
CREATE TABLE integration_connectors (id CHAR(32) PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,purpose TEXT NOT NULL,status ENUM('not_configured','awaiting_credentials','ready_for_test','connected','error','local') NOT NULL DEFAULT 'not_configured',implementation_status ENUM('contract_only','implemented','simulated','real_validated') NOT NULL DEFAULT 'contract_only',provider VARCHAR(80) NULL,config JSON NULL,secret_ciphertext TEXT NULL,requirements TEXT NOT NULL,last_event_at DATETIME NULL,last_test_at DATETIME NULL,last_test_result VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE integration_logs (id CHAR(32) PRIMARY KEY,connector_id CHAR(32) NOT NULL,level ENUM('info','warning','error') NOT NULL,message VARCHAR(500) NOT NULL,context JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(connector_id) REFERENCES integration_connectors(id) ON DELETE CASCADE,INDEX(connector_id,created_at));
CREATE TABLE automation_flows (id CHAR(32) PRIMARY KEY,name VARCHAR(150) NOT NULL,status ENUM('draft','published','inactive') NOT NULL DEFAULT 'draft',draft_version_id CHAR(32) NULL,published_version_id CHAR(32) NULL,created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE flow_versions (id CHAR(32) PRIMARY KEY,flow_id CHAR(32) NOT NULL,version_number INT NOT NULL,graph JSON NOT NULL,validation_errors JSON NULL,created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(flow_id) REFERENCES automation_flows(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),UNIQUE(flow_id,version_number));
ALTER TABLE automation_flows ADD FOREIGN KEY(draft_version_id) REFERENCES flow_versions(id),ADD FOREIGN KEY(published_version_id) REFERENCES flow_versions(id);
CREATE TABLE conversations (id CHAR(32) PRIMARY KEY,provider VARCHAR(50) NOT NULL,external_id VARCHAR(190) NOT NULL,phone VARCHAR(30) NULL,contact_id CHAR(32) NULL,opportunity_id CHAR(32) NULL,flow_version_id CHAR(32) NULL,current_node_id VARCHAR(80) NULL,state JSON NULL,automation_paused TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','waiting','human','closed','error') NOT NULL DEFAULT 'active',last_error TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(contact_id) REFERENCES contacts(id),FOREIGN KEY(opportunity_id) REFERENCES opportunities(id),FOREIGN KEY(flow_version_id) REFERENCES flow_versions(id),UNIQUE(provider,external_id));
CREATE TABLE conversation_messages (id CHAR(32) PRIMARY KEY,conversation_id CHAR(32) NOT NULL,provider VARCHAR(50) NOT NULL,external_message_id VARCHAR(190) NOT NULL,direction ENUM('in','out') NOT NULL,body TEXT NOT NULL,block_id VARCHAR(80) NULL,status ENUM('received','sent','simulated','failed') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,UNIQUE(provider,external_message_id));
